 if(id==='C014')return deFrame('inspection-scale','计划统筹 / 公开安排','部门计划怎样汇合，<br>检查怎样组织？','28个部门、64个领域、75条统筹规则分别描述组织规模、业务覆盖和规则数量。75条规则不能读成75个深度学习模型。',[c.period,c.scope,'来源 V07'],`<div class="de-stat-grid" style="--stat-count:3">${[['统筹部门',c.value[0],'个'],['检查领域',c.value[1],'个'],['统筹规则',c.value[2],'条']].map(([label,n,u])=>`<figure class="de-stat-card"><figcaption><small>不同计量分别展示</small><strong>${label}</strong></figcaption><div class="de-single"><b>${n}</b><span>${u}</span></div></figure>`).join('')}</div><div class="de-scene"><article><small>查前</small><h3>公示与计划统筹</h3><p>整合部门计划；8个安全部门检查计划提级置顶。</p></article><article><small>查中</small><h3>主动扫码与留痕</h3><p>记录检查主体、时间、内容和结果，企业可评价与反馈。</p></article><article><small>查后</small><h3>跟踪问效</h3><p>结果可查可追溯，继续优化填报和市区接口适配。</p></article></div>${routes}`);
 if(id==='C015')return deFrame('inspection-change','重点企业 / 公开统计','检查量怎样变化，<br>企业数与家次怎样区分？','758家是涉及的重点企业数量，2229家次是累计检查计量。54.2%沿用报道所述降幅，图表只将其转换为相对指数。',[c.period,'60平方公里 / 28部门','报道统计'],`${inspectionReduction("source:V07")}<div class="de-stat-grid de-inspection-context" style="--stat-count:2">${[['涉及重点企业',c.value[1],'家'],['累计检查',c.value[0],'家次']].map(([label,n,u])=>`<figure class="de-stat-card"><figcaption><small>${esc(c.period)}</small><strong>${label}</strong></figcaption><div class="de-single"><b>${fmt(n)}</b><span>${u}</span></div></figure>`).join('')}</div><p class="de-footnote">统计期、覆盖范围与报道口径一起阅读。这些报道数字不等于独立的因果效果评估。</p>${routes}`);
