function sourcePlotCard(claimId,title,svg,caption,kind='metric',interactive=true){
 // Source panels keep sixteen-pixel CJK text at their declared minimum widths.
 const minimumNative=kind==='analysis'?23:kind==='metric'?19:20;
 svg=svg.replace(/font-size="(\d+(?:\.\d+)?)"/g,(attr,size)=>Number(size)<minimumNative?`font-size="${minimumNative}"`:attr);
 // Inline source-only qualifier size outranks inherited .de-minimum CSS.
 svg=svg.replace('class="de-minimum"','class="de-minimum" style="font-size:19px"');
 const c=resolve(claimId,'claims'),tag=interactive?'button':'div',control=interactive?` data-action="claim:${esc(claimId)}" aria-label="展开${esc(c.title)}"`:'';return `<figure class="de-source-chart" data-source-claim="${esc(claimId)}" data-plot-kind="${kind}"><figcaption><small>${esc(c.period)}</small><strong>${esc(title)}</strong></figcaption><${tag} class="de-source-plot-button${interactive?'':' de-source-plot-static'}"${control}><span class="de-source-plot-scroll">${svg}</span>${interactive?'<span class="de-source-chart-open">展开对应记录 ↗</span>':''}</${tag}><p>${esc(caption)}</p></figure>`;
}
function sourceQuantification(id,{interactive=true}={}){
 const plot=(claimId,title,svg,caption,kind='metric')=>sourcePlotCard(claimId,title,svg,caption,kind,interactive);
 const metricSources={V01:['road',[0,1],['C008','C009']],V04:['supermarket',[0,1,2],['C005','C006','C007']],V05:['supermarket',[2],['C007']]};
 let cards=[],heading='本篇报道对应的数字',noteText='',facts='';
 if(metricSources[id]){
  const [caseId,indices,claims]=metricSources[id],c=resolve(caseId,'cases');
  cards=indices.map((index,i)=>plot(claims[i],c.metrics[index].label,caseMetricSvg(c.metrics[index]),resolve(claims[i],'claims').scope));
  noteText=id==='V05'?'符合联办条件的超市便利店跑动记录。':'各图保留自己的单位、适用场景和共同零起点。';
 }else if(id==='V06'){
  const c=resolve('C013','claims');heading='试点计划中的并列规模';noteText='高频事项与复用事项使用同一单位；事项、证照和套餐分别计量。';
  cards=[plot('C013','高频与复用事项计划',materialPlanSvg(),'计划安排 / 非完成数量','analysis')];
  facts=`<div class="de-source-statistics">${[['计划事项',c.value[0],'项'],['计划证照',c.value[1],'种'],['计划套餐',c.value[4],'个']].map(([label,n,unit])=>`<article><small>${label}</small><p><b class="de-data-number">${n}</b><span>${unit}</span></p></article>`).join('')}</div>`;
 }else if(id==='V07'){
  heading='总体统计与企业个案分别阅读';noteText='总体降幅转换为相对指数；一家企业自述另按次/年绘制。';
  cards=[plot('C015','总体检查量变化',inspectionChartSvg('index'),'2024.03—2025.07 / 28部门重点企业；100→45.8为相对指数','analysis'),plot('C016','一家企业的年度迎检',inspectionChartSvg('enterprise'),'2025年8月报道中的匿名单一企业自述','analysis')];
 }else if(id==='V11'){
  heading='先看实际事件，再看报道日期';noteText='后续跨区协作覆盖与早期60平方公里统计分别阅读。';
  cards=[plot('C032','综合监管跨区协作',inspectionTimelineSvg(),'圆形表示事件，方形表示来源发布。','wide')];
 }else if(id==='V13'){
  heading='年报异常信息修复的公开个案';noteText='迁入企业不到一周查询到移出异常名录，图中呈现公开报道的接续关系。';
  cards=[plot('C030','窗口如何接出跨区办理',creditRepairSvg(),'企业个案 / 不到一周','wide')];
 }else if(id==='V14'){
  heading='原时限与拟调整时限';noteText='市场监管领域处罚信息信用修复 / 工作日。';
  cards=[plot('C031','处罚信息信用修复',creditPlanSvg(),'2025年8月报道采用“将缩短”表述，图中保留拟调整状态。')];
 }
 return cards.length?`<section class="de-source-quantification" data-source-record="${esc(id)}"><header><small>公开出处 / 对应记录</small><h3>${heading}</h3><p>${noteText}</p></header><div class="de-source-plots" data-columns="${cards.length}">${cards.join('')}</div>${facts}</section>`:'';
}
function sourceAccess(s){return `<div class="de-source-access">${/^https?:\/\//.test(s.url||'')?`<a class="de-source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">打开发布主体原文 ↗</a>`:''}<span>发布 ${esc(s.publishedDate||'原文未载明')} · 台账核读 ${esc(s.verifiedDate||'未记录')}</span></div>`;}
function sourceExhibit(id='V04'){
 const s=resolve(id,'sources');if(!s)return '';
 const text=sourceTextExhibit(id);if(text)return text.replace('</header>','</header>'+sourceQuantification(id));
 const quant=sourceQuantification(id);if(!quant)return '';
 const access=sourceAccess(s),meta=[s.publisher,s.publishedDate,s.type];
 if(id==='V05')return deFrame('source','公开出处 / '+id,'符合联办条件时，<br>办事跑动怎样减少？',s.title,meta,`${access}${quant}<div class="de-evidence"><article><small>本篇报道</small><h3>证照联办与一业一证叠加</h3><p>${esc(s.note)}</p></article><article><small>继续对读</small><h3>同一主线的材料与时限</h3><p>材料与时限的主要出处在V04；在那里继续核对限定词及单位。</p><button data-action="source:V04">查看V04对应数字图 ↗</button></article></div>`);
 if(id==='V11')return deFrame('source','公开出处 / '+id,'跨区协作已经推进，<br>怎样与早期记录接续？',s.title,meta,`${access}${quant}<div class="de-evidence"><article><small>2025年后续进展</small><h3>联合检查与联动协议</h3><p>8月与通州开展跨区综合检查，12月与通州、大兴监管联席办签订协议，协作覆盖165平方公里。</p></article><article><small>回到早期统计</small><h3>范围与时期分别保留</h3><p>V07中60平方公里重点企业统计保留自己的期间。本篇公开进展为研究主线提供后续对读。</p><button data-action="source:V07">查看早期检查统计图 ↗</button></article></div>`);
 if(id==='V13'){
  const later=resolve('V01','sources');
  return deFrame('source','比较业务出处 / '+id,'不到一周完成修复，<br>背后怎样跨区接续？',s.title,meta,`${access}${quant}<div class="de-evidence"><article><small>本篇公开个案</small><h3>年报异常信息修复</h3><p>企业迁入后异地年报信息未及时同步。窗口联系商务金融局，由部门联络两地市场监管部门，完成信息查验、系统同步与材料审核。</p></article><article data-source-comparison="V01"><small>另一业务 / 道路开口</small><h3>早期报道与后续明确口径</h3><p>本篇2025年1月的道路段落表述为“最快15天”；${esc(later.publishedDate)}的V01明确30→15工作日。</p><button data-action="source:V01">核读后续V01工作日口径 ↗</button></article></div>`);
 }
 return deFrame('source','比较业务出处 / '+id,'处罚信息信用修复，<br>拟调整的时限是多少？',s.title,meta,`${access}${quant}<div class="de-evidence"><article><small>本篇安排</small><h3>保留拟调整状态</h3><p>处罚信息修复的办理时限拟由22工作日缩短至10工作日。适用对象是市场监管领域处罚信息修复。</p></article><article><small>另一信用修复对象</small><h3>年报异常紧急修复个案</h3><p>年报异常信息修复的不到一周记录在V13，按企业个案另行阅读。</p><button data-action="source:V13">对读年报异常修复个案 ↗</button></article></div>`);
}
function exhibitCredit(id){
 if(!['C030','C031'].includes(id))return '';
 const c=resolve(id,'claims'),sourceId=c.sourceIds[0],plan=id==='C031';
 return deFrame('credit','信用修复 / 比较业务',plan?'处罚信息修复，<br>拟调整时限怎样对照？':'年报异常信息修复，<br>怎样在不到一周接续办成？',plan?'原时限与拟调整时限使用同一单位，不与企业个案耗时合并。':'公开报道的迁入企业个案，从窗口咨询进入跨区信息核验。',[c.period,c.scope],`${sourceQuantification(sourceId,{interactive:false})}<nav class="de-route" aria-label="从信用修复比较记录继续">${deButton('source:'+sourceId,'对应出处','核读本项公开报道',sourceId,true)}${deButton('claim:'+(plan?'C030':'C031'),'另一业务对象',plan?'对读年报异常修复个案':'对读处罚信息拟调整时限','两种信用修复分别呈现')}${deButton('case-evidence:road','主线对照','回看道路开口与协调机制','流程协同 / 比较阅读')}</nav>`);
}
